# dots - keep ~/.config folders of selected apps in this repository and
# synchronise them between machines with Git. Synchronisation can be
# switched on and off at any time.

readonly CONF="${DOTS_CONF:-/etc/dots.conf}"
readonly STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/dots"
readonly AUTO_FLAG="$STATE_DIR/auto-sync"
readonly CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
readonly MAX_FILE_BYTES=$((5 * 1024 * 1024))

die() {
  echo "dots: $*" >&2
  exit 1
}

[[ -r "$CONF" ]] || die "missing $CONF (enable my.features.dots)"
# Generated by NixOS: REPO and APPS.
REPO="" APPS=""
# shellcheck disable=SC1090
. "$CONF"
[[ -n "$REPO" ]] || die "REPO missing in $CONF"
read -r -a APP_LIST <<<"$APPS"

git_repo() { git -C "$REPO" "$@"; }

branch() { git_repo rev-parse --abbrev-ref HEAD; }

usage() {
  cat <<'EOF2'
dots - synchronise app configuration between your machines

  dots status         links, pending changes, auto-sync state
  dots on | off       switch automatic synchronisation on or off
  dots sync           commit local changes, merge remote ones, push
  dots push           commit and push local changes only
  dots pull           fetch and apply remote changes only
  dots link           (re)create the ~/.config symlinks
  dots adopt [APP..]  move existing ~/.config/APP folders into the repository

Managed apps and repository path come from my.features.dots in your NixOS config.
EOF2
}

app_target() { echo "$REPO/config/$1"; }
app_link() { echo "$CONFIG_HOME/$1"; }

cmd_link() {
  local app link target
  mkdir -p "$CONFIG_HOME"
  for app in "${APP_LIST[@]}"; do
    link="$(app_link "$app")"
    target="$(app_target "$app")"
    mkdir -p "$target"
    if [[ -L "$link" ]]; then
      [[ "$(readlink "$link")" == "$target" ]] || {
        echo "dots: $link points elsewhere ($(readlink "$link")), leaving it"
      }
    elif [[ -e "$link" ]]; then
      echo "dots: $link is a real folder - run: dots adopt $app"
    else
      ln -s "$target" "$link"
      echo "dots: linked $link -> $target"
    fi
  done
}

cmd_adopt() {
  local apps=("$@") app link target backup ts
  [[ ${#apps[@]} -gt 0 ]] || apps=("${APP_LIST[@]}")
  ts="$(date +%Y%m%d-%H%M%S)"
  for app in "${apps[@]}"; do
    link="$(app_link "$app")"
    target="$(app_target "$app")"
    [[ -d "$link" && ! -L "$link" ]] || continue
    if [[ -n "$(find "$target" -mindepth 1 -print -quit 2>/dev/null)" ]]; then
      echo "dots: $app exists in the repository AND in $link; refusing to merge." >&2
      echo "      Compare both and remove one, then run: dots link" >&2
      continue
    fi
    backup="$STATE_DIR/backups/$ts/$app"
    mkdir -p "$backup" "$target"
    cp -a "$link/." "$backup/"
    cp -a "$link/." "$target/"
    rm -rf -- "$link"
    ln -s "$target" "$link"
    echo "dots: adopted $app (backup in $backup)"
  done
}

notify() {
  command -v notify-send >/dev/null 2>&1 && notify-send -a dots "dots" "$1" || true
  echo "dots: $1" >&2
}

commit_local() {
  git_repo add -A -- config
  # Refuse oversized files so that a stray cache cannot bloat the repository.
  local f size
  while IFS= read -r -d '' f; do
    size="$(stat -c %s -- "$REPO/$f")"
    if [[ "$size" -gt "$MAX_FILE_BYTES" ]]; then
      git_repo reset -q -- "$f"
      notify "skipped $f (larger than 5 MB)"
    fi
  done < <(git_repo diff --cached --name-only --diff-filter=AM -z -- config)

  if ! git_repo diff --cached --quiet -- config; then
    git_repo commit -q -m "dots: $(hostname) $(date -Iseconds)" -- config
    echo "dots: committed local changes"
  fi
}

fetch_remote() {
  git_repo fetch -q origin "$(branch)" || {
    notify "cannot reach the remote; try again later"
    return 1
  }
}

apply_remote() {
  local b
  b="$(branch)"
  git_repo rev-parse -q --verify "origin/$b" >/dev/null || return 0
  if [[ "$(git_repo rev-list --count "HEAD..origin/$b")" -gt 0 ]]; then
    if ! git_repo rebase -q --autostash "origin/$b" 2>/dev/null; then
      git_repo rebase --abort 2>/dev/null || true
      notify "conflict between local and remote config; auto-sync switched off. Resolve in $REPO"
      rm -f -- "$AUTO_FLAG"
      return 1
    fi
    echo "dots: applied remote changes"
  fi
}

push_local() {
  local b
  b="$(branch)"
  if [[ "$(git_repo rev-list --count "origin/$b..HEAD" 2>/dev/null || echo 1)" -gt 0 ]]; then
    git_repo push -q origin "$b" || {
      notify "push failed"
      return 1
    }
    echo "dots: pushed"
  fi
}

cmd_sync() {
  [[ "$(git_repo rev-parse --git-dir)" ]] || die "$REPO is not a Git repository"
  commit_local
  fetch_remote || return 1
  apply_remote || return 1
  push_local
}

cmd_status() {
  local app link target state b
  for app in "${APP_LIST[@]}"; do
    link="$(app_link "$app")"
    target="$(app_target "$app")"
    if [[ -L "$link" && "$(readlink "$link")" == "$target" ]]; then
      state="linked"
    elif [[ -d "$link" && ! -L "$link" ]]; then
      state="local folder (dots adopt $app)"
    elif [[ -e "$link" || -L "$link" ]]; then
      state="other link"
    else
      state="missing (dots link)"
    fi
    printf '%-12s %s\n' "$app" "$state"
  done
  echo
  b="$(branch)"
  echo "branch:   $b"
  echo "auto:     $([[ -e "$AUTO_FLAG" ]] && echo on || echo off)"
  echo "pending:"
  git_repo status --short -- config | sed 's/^/  /'
  if git_repo rev-parse -q --verify "origin/$b" >/dev/null; then
    echo "ahead/behind origin: $(git_repo rev-list --count "origin/$b..HEAD") / $(git_repo rev-list --count "HEAD..origin/$b")"
  fi
}

cmd="${1:-status}"
[[ $# -gt 0 ]] && shift
case "$cmd" in
  help | -h | --help) usage ;;
  status) cmd_status ;;
  link) cmd_link ;;
  adopt) cmd_adopt "$@" ;;
  sync) cmd_sync ;;
  push) commit_local; fetch_remote; push_local ;;
  pull) fetch_remote; apply_remote ;;
  on)
    mkdir -p "$STATE_DIR"
    touch "$AUTO_FLAG"
    echo "dots: automatic sync on (every few minutes while you are logged in)"
    ;;
  off)
    rm -f -- "$AUTO_FLAG"
    echo "dots: automatic sync off"
    ;;
  auto) # used by the systemd timer
    [[ -e "$AUTO_FLAG" ]] || exit 0
    cmd_sync
    ;;
  *) die "unknown command '$cmd' (see dots help)" ;;
esac
